mapper.select:
SELECT CAST(om.order_id AS CHAR) AS orderId, om.status AS orderStatus, om.start_at AS startAt, om.end_at AS endAt, om.day_num AS dayNum, CASE WHEN om.settlement_amount_cent > 0 THEN om.settlement_amount_cent WHEN om.total_pay_price_cent > 0 THEN GREATEST( om.total_pay_price_cent - COALESCE(do.commission_price_cent, om.distribution_commission_cent, om.commission_price_cent, 0), 0 ) ELSE GREATEST( om.total_price_cent - COALESCE(do.commission_price_cent, om.distribution_commission_cent, om.commission_price_cent, 0), 0 ) END AS businessIncomeCent FROM order_main om LEFT JOIN distribution_order do ON do.source_order_id = om.order_id AND do.camp_id = om.camp_id AND (do.channel_id = om.channel_id OR do.channel_id IS NULL) LEFT JOIN channel_account ca ON ca.account_id = om.channel_id AND ca.camp_id = om.camp_id LEFT JOIN room_category rc ON rc.room_category_id = om.room_category_id AND rc.camp_id = om.camp_id WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.order_type = 'daily_room' AND om.status NOT IN ('cancelled', 'refunded', 'pending') AND om.start_at < #{rangeEndExclusive} AND om.end_at > #{rangeStart}
AND om.poi_id = #{poiId}
AND om.room_category_id = #{roomCategoryId}
AND rc.group_id = #{roomCategoryGroupId}
AND ca.channel_id = #{channelId}
AND om.room_id = #{roomId}
ORDER BY om.start_at ASC, om.order_id ASC

SELECT
    CAST(ct.clean_task_id AS CHAR) AS taskId,
    ct.task_type AS taskType,
    ct.task_status AS taskStatus,
    ct.deadline_at AS deadlineAt
FROM clean_task ct
LEFT JOIN room_category rc ON rc.room_category_id = ct.room_category_id
    AND rc.camp_id = ct.camp_id
WHERE ct.camp_id = #{campId}
  AND ct.deadline_at >= #{rangeStart}
  AND ct.deadline_at < #{rangeEndExclusive}

    AND ct.poi_id = #{poiId}


    AND ct.room_category_id = #{roomCategoryId}


    AND rc.group_id = #{roomCategoryGroupId}


    AND ct.room_id = #{roomId}

ORDER BY ct.deadline_at ASC, ct.clean_task_id ASC
